def outline_tower(minimum_y=100):
    """1px dark-plum outline around the solid masonry/deck parts, on the sky side only."""
    add = set()
    for (x, y) in SOLID:
        if y < minimum_y:
            continue
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            n = (x + dx, y + dy)
            if n not in SOLID and 0 <= n[0] < W and 0 <= n[1] < H and in_open(n[0], n[1]):
                add.add(n)
    for (x, y) in add:
        put(x, y, TOWER[0])


